using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using EchoSphere.Core;
// Read-only delivery coverage and import settings. UI/race fixture is separate.
public static class ArchiveIllustrationCoverage {
 public static object Main(){int checks=0;void Check(bool b,string why){checks++;if(!b)throw new Exception(why);}var ids=BestiaryCatalog.All.Select(e=>e.Id).Concat(CharacterRules.All.Select(c=>"character:"+CharacterRules.ToSourceId(c.Id))).ToArray();var hashes=new System.Collections.Generic.HashSet<string>();
 foreach(string id in ids){string path="Assets/Resources/EchoSphere/ArchiveIllustrations/"+id.Replace(':','-')+".jpg";Check(File.Exists(path),"Missing illustration "+id);using(var sha=System.Security.Cryptography.SHA256.Create())Check(hashes.Add(Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(path)))),"Repeated image "+id);var importer=(TextureImporter)AssetImporter.GetAtPath(path);Check(importer!=null&&!importer.isReadable&&!importer.mipmapEnabled,"CPU/mip policy "+id);Check(importer.textureType==TextureImporterType.Default&&importer.wrapMode==TextureWrapMode.Clamp,"Type/wrap "+id);var android=importer.GetPlatformTextureSettings("Android");Check(android.overridden&&android.format==TextureImporterFormat.ASTC_6x6,"Android format "+id);importer.GetSourceTextureWidthAndHeight(out int w,out int h);Check(w==768&&h==512,"Dimensions "+id);}
 var result=new{status="PASS",checks,illustrations=ids.Length,scope="all reachable bestiary and character images, unique files, Android compression and retained-detail delivery settings; no save edits"};Directory.CreateDirectory("Library/archive-illustrations");File.WriteAllText("Library/archive-illustrations/coverage.json",Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;}
}
